import csv
path='/tmp/WEOApr2025all.xls'
with open(path, 'r', encoding='utf-16-le') as f:
    reader=csv.reader(f, delimiter='\t')
    header=next(reader)
    years=header[9:]
    # map year to index
    year_idx={y:i for i,y in enumerate(years)}
    target_years=[str(y) for y in range(2020,2031)]
    rows={}
    for row in reader:
        if len(row)<5: continue
        if row[3]=='Georgia' and row[2] in {'NGDP_R','NGDP_RPCH','NGDP_D'}:
            rows[row[2]]=row
    for ind,row in rows.items():
        vals={y: row[9+year_idx[y]] if y in year_idx else None for y in target_years}
        print(ind, vals)
